"use strict";
import { AnimatePresence, motion } from "framer-motion";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { getPositionUrl } from "components/Liquidity/utils";
import { useState } from "react";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
import { Chevron, Infinity, Shrink } from "ui/src/components/icons";
import { formatCurrencyAmount } from "utils/formatCurrencyAmount";
import { useDashContext } from "../DashContextProvider";
import StakedUnstakedAprEmissionsTradingFees from "./StakedUnstakedAprEmissionsTradingFees";
import TokenDetails from "./TokenDetails";
const ToggleButton = styled.button`
  all: unset;
  display: flex;
  gap: 4px;
  padding: 12px 18px;
  cursor: pointer;
  border-radius: 10px;
  align-items: center;
`;
export default function PoolLiquidityRewards({ poolGroup, isLoading }) {
  const colors = useSporeColors();
  const { expandCollapse } = useDashContext();
  if (isLoading) {
    return <Flex flexDirection="column" gap={"$gap12"}>
        <Flex
      style={{
        background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
      }}
      py={"$spacing24"}
      px={"$spacing20"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      opacity={0.6}
    >
          <Flex row gap={"$gap12"} justifyContent="space-between">
            <TokenDetails isLoading={true} />
            <Flex flexDirection="column" gap={"$gap12"} justifyContent="center" alignItems="flex-end">
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Text variant="body3" fontSize={"$mdall"}>
                N/A
              </Text>
            </Flex>
          </Flex>
        </Flex>
      </Flex>;
  }
  if (!poolGroup) {
    return null;
  }
  const totalValue = "N/A";
  const token0Symbol = poolGroup.representative.currency0Amount?.currency.symbol || "";
  const token1Symbol = poolGroup.representative.currency1Amount?.currency.symbol || "";
  let totalToken0Amount = poolGroup.positions.reduce((sum, pos) => {
    return sum + parseFloat(formatCurrencyAmount(pos.currency0Amount, 6) || "0");
  }, 0);
  let totalToken1Amount = poolGroup.positions.reduce((sum, pos) => {
    return sum + parseFloat(formatCurrencyAmount(pos.currency1Amount, 6) || "0");
  }, 0);
  return <Flex flexDirection="column" gap={"$gap12"}>
      {
    /* Pool Header - shown once */
  }
      <Flex
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
    py={"$spacing24"}
    px={"$spacing20"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    hoverStyle={{ borderColor: "$surface3Hovered" }}
  >
        <Flex
    row
    gap={"$gap12"}
    justifyContent="space-between"
    $md={{ flexDirection: "column", justifyContent: "flex-start" }}
  >
          <TokenDetails position={poolGroup.representative} />

          <Flex flexDirection="column" gap={"$gap24"} width={"unset"} $md={{ width: "100%" }}>
            <Flex
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $md={{ row: true, justifyContent: "space-between", mt: "$gap12" }}
  >
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Text variant="body3" fontSize={"$mdall"}>
                {totalValue}
              </Text>
            </Flex>

            <Text $lg={{ display: "none" }} variant="body3" color={"$neutral2"}>
              {totalToken0Amount.toFixed(4)} {token0Symbol} + {totalToken1Amount.toFixed(4)} {token1Symbol}
            </Text>
          </Flex>
        </Flex>
      </Flex>

      {
    /* Individual Positions */
  }
      {poolGroup.positions.map((position, index) => {
    const PositionRow = () => {
      const [isExpanded, setIsExpanded] = useState(expandCollapse);
      const positionId = position?.tokenId ? `#${position.tokenId}` : `#${index + 1}`;
      const isV3 = position?.version === ProtocolVersion.V3;
      const isGaugePosition = position?.isGaugePosition;
      const positionUrl = getPositionUrl(position);
      const liquidityAmount = position?.liquidity ? parseFloat(position.liquidity).toFixed(0) : "0";
      const getStatusColor = () => {
        switch (position?.status) {
          case PositionStatus.IN_RANGE:
            return colors.statusSuccess.val;
          case PositionStatus.OUT_OF_RANGE:
            return colors.statusCritical.val;
          case PositionStatus.CLOSED:
            return colors.neutral3.val;
          default:
            return colors.neutral3.val;
        }
      };
      return <Flex
        flexDirection="column"
        ml={"$spacing12"}
        $md={{ ml: 0 }}
        borderRadius={"$rounded12"}
        borderWidth={1}
        borderColor={"$surface3"}
        transition="all 0.2s ease"
        hoverStyle={{ backgroundColor: "$surface1Hovered" }}
      >
              <ToggleButton
        onClick={() => setIsExpanded(!isExpanded)}
        type="button"
        role="button"
        aria-label="toggle-position-details"
      >
                <Flex row gap={"$gap12"} justifyContent="space-between" alignItems="center" width={"100%"}>
                  <Flex row gap={"$gap16"} alignItems="center">
                    <Chevron
        transition="transform 0.2s ease"
        transform={isExpanded ? "rotate(270deg)" : "rotate(180deg)"}
        size={20}
        color={"$neutral1"}
      />
                    <Text variant="buttonLabel4">
                      {isGaugePosition ? position?.version === ProtocolVersion.V2 ? "Gauge LP Position" : `Gauge Position ${positionId}` : position?.version === ProtocolVersion.V2 ? "LP Position" : `Position ${positionId}`}
                    </Text>
                    {isGaugePosition && <Flex
        backgroundColor={"$statusSuccess"}
        px={"$spacing4"}
        py={"$spacing2"}
        borderRadius={"$rounded4"}
      >
                        <Text variant="body4" fontSize={10} color={"$surface1"} fontWeight="600">
                          STAKED
                        </Text>
                      </Flex>}
                  </Flex>

                  <Flex row gap={"$gap12"} alignItems="center">
                    <Flex $lg={{ display: "none" }}>
                      <CurrencyDetails
        position={position}
        liquidityAmount={liquidityAmount}
        isV3={isV3}
        getStatusColor={getStatusColor}
      />
                    </Flex>
                    <Link to={positionUrl} className="text-decoration-none" onClick={(e) => e.stopPropagation()}>
                      <Flex
        py={"$spacing8"}
        px={"$spacing12"}
        borderRadius={"$rounded12"}
        transition="all 0.2s ease"
        borderWidth={1}
        borderColor={"$surface3"}
        backgroundColor={"$surface1"}
        hoverStyle={{ backgroundColor: "$surface1Hovered" }}
      >
                        <Text variant="buttonLabel4">{isGaugePosition ? "View Gauge" : "Manage"}</Text>
                      </Flex>
                    </Link>
                  </Flex>
                </Flex>
              </ToggleButton>

              {
        /* Expandable content */
      }
              <AnimatePresence>
                {isExpanded && <motion.div
        initial={{ height: 0, opacity: 0 }}
        animate={{ height: "auto", opacity: 1 }}
        exit={{ height: 0, opacity: 0 }}
        transition={{
          height: { duration: 0.3, ease: "easeInOut" },
          opacity: { duration: 0.2, ease: "easeOut" }
        }}
        style={{ overflow: "hidden", padding: "12px 18px" }}
      >
                    <Flex display="none" $lg={{ display: "block" }} mb={"$spacing24"}>
                      <CurrencyDetails
        position={position}
        liquidityAmount={liquidityAmount}
        isV3={isV3}
        getStatusColor={getStatusColor}
      />
                    </Flex>
                    <StakedUnstakedAprEmissionsTradingFees position={position} isLoading={false} />
                  </motion.div>}
              </AnimatePresence>
            </Flex>;
    };
    return <PositionRow key={`${poolGroup.poolKey}-${index}`} />;
  })}
    </Flex>;
}
const CurrencyDetails = ({
  position,
  liquidityAmount,
  isV3,
  getStatusColor
}) => <Flex row $md={{ flexDirection: "column", alignItems: "flex-start" }} gap={"$gap12"} alignItems="center">
    <Text variant="body4" color={"$neutral2"}>
      {formatCurrencyAmount(position.currency0Amount, 4)} {position.currency0Amount?.currency.symbol} +{" "}
      {formatCurrencyAmount(position.currency1Amount, 4)} {position.currency1Amount?.currency.symbol}
    </Text>

    <Flex row gap={"$gap8"} alignItems="center">
      <Text variant="buttonLabel4">{liquidityAmount}</Text>
      {isV3 ? <>
          <Shrink size={18} color={getStatusColor()} />
          {position?.tickLower && position?.tickUpper ? <Text variant="buttonLabel4" color={"$neutral2"}>
              [{position.tickLower}, {position.tickUpper}]
            </Text> : <Infinity size={14} color={"$neutral1"} />}
        </> : <Infinity size={14} color={"$neutral1"} />}
    </Flex>
  </Flex>;
